<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue';
import type {TranscriptEdits} from './transcript-journal';
import type {TranscriptSegment} from '../../shared/api/transcripts';
const props=withDefaults(defineProps<{value:TranscriptEdits;editable:boolean;busy:boolean;dirty:boolean;conflict:TranscriptEdits|null;conflictToken:string|null;state:string;blocked:boolean;blockedReason?:string;storageStatus:string;error:string|null;confirmed:boolean;canConfirm:boolean;pendingSave?:boolean;revisionToken?:string;commit?:(value:TranscriptEdits,expected:string)=>Promise<boolean>;showFooter?:boolean;provenance?:Array<Pick<TranscriptSegment,'segmentId'|'sourceFileId'|'startMs'|'endMs'|'speakerId'>>;playableFiles?:string[]}>(),{showFooter:true});
const emit=defineEmits<{edit:[value:TranscriptEdits];save:[];confirm:[];retry:[];reload:[];discard:[];reapply:[];begin:[];tools:[];seek:[fileId:string,startMs:number]}>();
const query=ref(''),pendingOnly=ref(false),composing=ref(false),editDialog=ref<HTMLDialogElement>(),replaceDialog=ref<HTMLDialogElement>(),editText=ref(''),modalError=ref<string|null>(null),modalBusy=ref(false),find=ref(''),replacement=ref(''),replacementCount=ref<number|null>(null);
let editing:string|null=null,modalValue='',modalRevision='',attempted=false,submittedValue:string|null=null,replacementHits=0,toastTimer:ReturnType<typeof setTimeout>|null=null;
const filtered=computed(()=>props.value.map((segment,index)=>({segment,index})).filter(({segment})=>(!query.value||segment.body.toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))&&(!pendingOnly.value||segment.marks.includes('DISPUTE'))));
const visible=filtered;
const modalBlocked=computed(()=>modalBusy.value||props.busy||pending.value||props.pendingSave);
watch(()=>props.editable,allowed=>{if(!allowed){editDialog.value?.close();replaceDialog.value?.close();editText.value='';find.value='';replacement.value='';modalError.value=null;composing.value=false;}});
const pending=computed(()=>!['EMPTY','ACKNOWLEDGED','CONFLICT','REJECTED'].includes(props.state));
const labels:Record<TranscriptSegment['marks'][number],string>={KEY:'关键',CONCLUSION:'结论',DISPUTE:'争议',GENERATION_FOCUS:'重点生成'};
const timing=computed(()=>new Map((props.provenance??[]).map(s=>[s.segmentId,s])));
function clock(ms:number){const seconds=Math.floor(ms/1000);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function seek(id:string){const source=timing.value.get(id);if(source&&source.startMs!==null&&props.playableFiles?.includes(source.sourceFileId))emit('seek',source.sourceFileId,source.startMs);}
function openModal(kind:'edit'|'replace',id?:string){if(!props.editable||props.blocked||props.busy||pending.value||props.pendingSave)return;editing=id??null;editText.value=props.value.find(s=>s.segmentId===id)?.body??'';find.value='';replacement.value='';modalError.value=null;attempted=false;submittedValue=null;replacementHits=0;modalRevision=props.revisionToken??'';modalValue=JSON.stringify(props.value);(kind==='edit'?editDialog.value:replaceDialog.value)?.showModal();}
function closeModal(kind:'edit'|'replace',event?:Event){if(modalBlocked.value){event?.preventDefault();return;}(kind==='edit'?editDialog.value:replaceDialog.value)?.close();composing.value=false;}
function backdrop(kind:'edit'|'replace',event:MouseEvent){const dialog=kind==='edit'?editDialog.value:replaceDialog.value;if(!dialog||event.target!==dialog)return;const b=dialog.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)closeModal(kind,event);}
function changed(){return modalRevision!==(props.revisionToken??'')||modalValue!==JSON.stringify(props.value)&&submittedValue!==JSON.stringify(props.value);}
async function commit(next:TranscriptEdits,kind:'edit'|'replace'){
 if(modalBusy.value||props.busy||composing.value||props.blocked||!props.editable)return false;
 if(!((pending.value||props.pendingSave)&&attempted)&&changed()){modalError.value='转写或纠错已变化，请核对后重试';return false;}
 if(!props.commit){modalError.value='保存暂不可用，请保留修改并重新读取。';return false;}
 modalBusy.value=true;modalError.value=null;attempted=true;submittedValue=JSON.stringify(next);
 try{const saved=await props.commit(next,modalRevision);if(saved){(kind==='edit'?editDialog.value:replaceDialog.value)?.close();composing.value=false;return true;}modalError.value=props.error??'保存尚未确认，修改已保留，请重试原请求。';return false;}
 catch(cause){modalError.value=cause instanceof Error?cause.message:'保存失败，请保留修改并重试。';return false;}finally{modalBusy.value=false;}
}
async function saveSegment(){if(composing.value)return;const text=editText.value.trim();if(!text){modalError.value='请输入有效转写内容';return;}const item=props.value.find(s=>s.segmentId===editing);if(!item){modalError.value='转写片段已变化，请重新核对';return;}await commit(props.value.map(s=>s.segmentId===editing?{...s,body:text}:s),'edit');}
function mark(index:number,key:TranscriptSegment['marks'][number],checked:boolean){emit('edit',props.value.map((s,i)=>i===index?{...s,marks:checked?[...s.marks,key]:s.marks.filter(m=>m!==key)}:s));}

async function replaceAll(){if(composing.value)return;const old=find.value.trim(),text=replacement.value.trim();if(!old||!text){modalError.value='请输入查找与替换内容';return;}const count=props.value.reduce((n,s)=>n+s.body.split(old).length-1,0);if(!count&&!attempted){modalError.value='未找到匹配内容，未执行替换';return;}if(!attempted)replacementHits=count;if(await commit(props.value.map(s=>({...s,body:s.body.split(old).join(text)})),'replace')){replacementCount.value=replacementHits;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>{replacementCount.value=null;},4000);}}
onUnmounted(()=>{if(toastTimer)clearTimeout(toastTimer);});
defineExpose({composing});
</script>
<template><section class="card transcript-section" aria-labelledby="transcript-title">
 <div class="card-h aci-inline-toolbar"><div class="aci-inline-title-row"><h2 id="transcript-title" class="card-t" style="font-size:14px">转写稿</h2><span class="aci-inline-count" aria-live="polite">{{confirmed?'已确认':'待确认'}} <b>{{value.length}}</b> 段</span><button v-if="!editable&&showFooter" class="btn sm transcript-begin" :disabled="busy||blocked" @click="emit('begin')">建立人工工作版本</button></div><div class="aci-inline-controls"><div class="aci-inline-search-row"><div class="search-box"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 5 5"/></svg><input v-model="query" class="input" placeholder="搜索转写" aria-label="搜索转写"/></div><label class="aci-inline-pending"><input v-model="pendingOnly" type="checkbox"/>待确认问题</label></div><div class="aci-inline-toolbar-actions"><button class="btn sm aci-inline-accept" disabled title="纠错建议服务尚未接入">全部接受</button><button class="btn sm" disabled title="纠错建议服务尚未接入">全部拒绝</button><span class="aci-inline-action-divider"></span><button class="btn sm ghost" :disabled="!editable||blocked||busy||pending" @click="openModal('replace')">批量替换</button></div></div></div>
 <div class="transcript-notices"><p v-if="error" role="alert">{{error}}</p><p v-if="blocked" role="alert">{{blockedReason??'本地恢复记录暂不可用，请保留页面并重新读取。'}}</p><p v-else-if="storageStatus==='INVALID'||storageStatus==='UNAVAILABLE'" role="alert">草稿暂未写入恢复记录，请保持页面打开并重试保存。</p><p v-if="pending" role="status">原操作结果待恢复。重试将保留原请求；后续输入仍保留在本地草稿。</p><div v-if="conflict" class="conflict" role="alert"><h3>服务器已有更新（版本 {{conflictToken}}）</h3><p>你的草稿已保留，请比较后处理。</p><details><summary>查看最新保存内容</summary><p v-for="s in conflict" :key="s.segmentId" class="text">{{s.body}}</p></details><button class="btn" :disabled="busy||pending||blocked" @click="emit('reapply')">将我的修改应用到最新版本</button><button class="btn" :disabled="busy||pending||blocked" @click="emit('discard')">放弃本地修改，读取最新版本</button></div></div>
 <div class="card-p transcript-paragraphs" style="padding-top:12px"><div v-for="{segment,index} in visible" :key="segment.segmentId" class="seg" :id="'seg-'+segment.segmentId"><button class="s-time" type="button" :aria-label="'定位原录音第 '+(index+1)+' 段'" :title="timing.get(segment.segmentId)?.startMs!=null&&playableFiles?.includes(timing.get(segment.segmentId)!.sourceFileId)?'点击定位音频':'此片段无对应原录音'" :aria-disabled="timing.get(segment.segmentId)?.startMs==null||!playableFiles?.includes(timing.get(segment.segmentId)!.sourceFileId)" @click="seek(segment.segmentId)">{{timing.get(segment.segmentId)?.startMs!=null?clock(timing.get(segment.segmentId)!.startMs!):String(index+1).padStart(2,'0')}}</button><div class="s-body"><div class="s-spk"><span class="spk-av" style="background:var(--blue)">文</span><span class="b" style="font-size:12.5px;color:var(--blue)">文本段落</span><button v-if="editable" class="btn sm ghost aci-segment-edit" :disabled="blocked||busy||pending" :aria-label="'编辑第 '+(index+1)+' 段'" @click="openModal('edit',segment.segmentId)">✎</button></div><div class="s-text">{{segment.body}}</div><div class="s-marks"><button v-for="(label,key) in labels" :key="key" class="mk" :class="segment.marks.includes(key)?'on-'+({KEY:'key',CONCLUSION:'con',DISPUTE:'dis',GENERATION_FOCUS:'gen'}[key]):''" :disabled="!editable||blocked" :aria-pressed="segment.marks.includes(key)" @click="mark(index,key,!segment.marks.includes(key))">{{label}}</button></div></div></div><div v-if="!visible.length" class="empty">没有符合条件的转写段落</div></div>
 <details v-if="showFooter" class="transcript-recovery"><summary>版本与恢复操作</summary><div class="flex"><button class="btn sm" @click="emit('tools')">纠错建议与候选</button><button class="btn sm" :disabled="busy" @click="emit('reload')">重新读取</button><button v-if="pending||state==='ACKNOWLEDGED'" class="btn sm" :disabled="busy||blocked" @click="emit('retry')">恢复原操作结果</button><button v-if="dirty||state==='CONFLICT'||state==='REJECTED'" class="btn sm" :disabled="busy||pending||blocked" @click="emit('discard')">放弃本地修改／已拒绝操作</button></div></details>
 <footer v-if="showFooter&&(!confirmed||dirty)" class="acf-dock"><div class="acf-inner"><span class="acf-hint">{{dirty?'有尚未保存的修改，确认前将保存当前工作版本。':confirmed?'当前转写已确认，可继续生成会议纪要。':'确认转写后，将使用已保存的转写内容生成纪要。'}}</span><div class="acf-actions"><button class="btn primary" :disabled="busy||blocked||!!conflict||pending||composing||!canConfirm&&!confirmed||!['EMPTY','ACKNOWLEDGED'].includes(state)" @click="emit('confirm')">确认转写并生成纪要</button></div></div></footer>
 <dialog ref="editDialog" class="modal lg transcript-modal" aria-labelledby="transcript-edit-title" @cancel="closeModal('edit',$event)" @click="backdrop('edit',$event)"><header class="modal-h"><h3 class="m-t" id="transcript-edit-title">编辑转写片段</h3><button type="button" class="m-x" aria-label="关闭" :disabled="modalBlocked" @click="closeModal('edit')">×</button></header><div class="modal-b"><div class="field"><label for="transcript-edit-text">转写内容</label><textarea id="transcript-edit-text" v-model="editText" class="input" rows="8" aria-label="转写内容" :readonly="modalBlocked||blocked" @compositionstart="composing=true" @compositionend="composing=false"/></div><div class="small muted">保存当前工作稿，原始留档不变；本段旧建议需重新核对，既有确认和纪要保留。</div><div v-if="modalError" class="ac-error" role="alert">{{modalError}}</div></div><footer class="modal-f"><button class="btn" :disabled="modalBlocked" @click="closeModal('edit')">取消</button><button class="btn primary" :disabled="modalBusy||busy||blocked||composing||!editable" @click="saveSegment">保存</button></footer></dialog>
 <dialog ref="replaceDialog" class="modal transcript-modal" aria-labelledby="replace-title" @cancel="closeModal('replace',$event)" @click="backdrop('replace',$event)"><header class="modal-h"><h3 id="replace-title" class="m-t">批量替换</h3><button type="button" class="m-x" aria-label="关闭" :disabled="modalBlocked" @click="closeModal('replace')">×</button></header><div class="modal-b"><div class="field"><label for="transcript-find">查找</label><input id="transcript-find" v-model="find" class="input" aria-label="查找" :readonly="modalBlocked||blocked" @compositionstart="composing=true" @compositionend="composing=false"/></div><div class="field"><label for="transcript-replacement">替换为</label><input id="transcript-replacement" v-model="replacement" class="input" aria-label="替换为" :readonly="modalBlocked||blocked" @compositionstart="composing=true" @compositionend="composing=false"/></div><div class="small muted">作用于本会议当前工作稿全文，不受搜索或问题筛选影响；受影响段落的旧纠错需重新核对，原始留档不变。</div><div v-if="modalError" class="ac-error" role="alert">{{modalError}}</div></div><footer class="modal-f"><button class="btn" :disabled="modalBlocked" @click="closeModal('replace')">取消</button><button class="btn primary" :disabled="modalBusy||busy||blocked||composing||!editable" @click="replaceAll">替换</button></footer></dialog>
 <div v-if="replacementCount!==null" class="toast-wrap" role="status"><div class="toast"><div><div class="t-t">替换完成</div><div class="t-d">共替换 {{replacementCount}} 处</div></div></div></div>
</section></template>
<style scoped>.transcript-section{padding:0;overflow:hidden}.transcript-notices:empty{display:none}.transcript-notices:not(:empty){padding:12px 20px}.transcript-notices [role=alert]{color:#9a3412}.s-text{white-space:pre-wrap;overflow-wrap:anywhere}.segment-input{width:100%;padding:10px;border:1px solid var(--border2);border-radius:6px;font:inherit;line-height:1.8;resize:vertical}.mk{font-family:inherit}.transcript-recovery{padding:12px 20px;border-top:1px solid var(--border);font-size:12px;color:var(--muted)}.transcript-recovery summary{cursor:pointer}.transcript-recovery .flex{margin-top:10px}.acf-inner{max-width:1552px;margin:auto;display:flex;align-items:center;gap:18px}.acf-hint{flex:1;min-width:0;font-size:12px;color:var(--muted)}.acf-actions{display:flex;gap:10px}.conflict{background:#fff5dc;padding:12px}.notice-dialog .input{display:block;width:100%}@media(max-width:800px){.acf-inner{flex-wrap:wrap;gap:10px}.acf-actions{margin-left:auto}.s-time{display:none}}</style>

<style scoped>.aci-inline-toolbar .aci-inline-title-row .transcript-begin.btn.sm{margin-left:auto;height:22px;min-height:22px;padding:2px 8px;line-height:18px}</style>

<style scoped>.s-time{border:0;background:transparent;padding:0;text-align:left;cursor:pointer}.s-time[aria-disabled=true]{cursor:default;color:var(--muted)}</style>

<style scoped>.transcript-modal{border:0;padding:0;margin:auto;color:var(--text)}.transcript-modal:not([open]){display:none}.transcript-modal::backdrop{background:rgba(17,24,73,.42);backdrop-filter:blur(2px)}.transcript-modal .m-t{margin:0}.transcript-modal .input{width:100%}.transcript-modal textarea{resize:vertical}.transcript-modal .ac-error{margin-top:12px}</style>
